.cmp-dynamic-tabs { width: 100%; }
.cmp-dynamic-tabs__tablist { display: flex; flex-wrap: wrap; gap: var(--tabs-gap, 0.5rem); margin: 0; padding: 0; border-bottom: 1px solid var(--tabs-border-color, currentColor); }
.cmp-dynamic-tabs__tab { appearance: none; border: 0; border-bottom: 3px solid transparent; margin: 0 0 -1px; padding: 0.75rem 1rem; background: transparent; color: inherit; font: inherit; cursor: pointer; }
.cmp-dynamic-tabs__tab[aria-selected="true"] { border-bottom-color: var(--tabs-active-color, currentColor); font-weight: 700; }
.cmp-dynamic-tabs__tab:focus-visible, .cmp-dynamic-tabs__tabpanel:focus-visible { outline: 2px solid var(--tabs-focus-color, currentColor); outline-offset: 3px; }
.cmp-dynamic-tabs__tabpanel[hidden] { display: none !important; }
.cmp-dynamic-tabs__tabpanel { padding: 1rem 0; }
@media (max-width: 40rem) { .cmp-dynamic-tabs__tablist { flex-wrap: nowrap; overflow-x: auto; } .cmp-dynamic-tabs__tab { flex: 0 0 auto; } }

(function () {
  'use strict';
  var selector = '[data-cmp-is="tabs"]';
  function owned(root, childSelector) {
    return Array.prototype.filter.call(root.querySelectorAll(childSelector), function (node) {
      return node.closest(selector) === root;
    });
  }
  function initialize(root) {
    if (root.getAttribute("data-tabs-initialized") === "true") return;
    root.setAttribute("data-tabs-initialized", "true");
    var tabs = owned(root, '[role="tab"]');
    var panels = owned(root, '[role="tabpanel"]');
    if (!tabs.length || !panels.length) return;
    function activate(tab, moveFocus) {
      var panelId = tab.getAttribute("aria-controls");
      tabs.forEach(function (item) {
        var selected = item === tab;
        item.setAttribute("aria-selected", selected ? "true" : "false");
        item.tabIndex = selected ? 0 : -1;
      });
      panels.forEach(function (panel) { panel.hidden = panel.id !== panelId; });
      if (moveFocus) tab.focus();
    }
    tabs.forEach(function (tab, index) {
      tab.addEventListener("click", function () { activate(tab, false); });
      tab.addEventListener("keydown", function (event) {
        var next = index;
        if (event.key === "ArrowRight") next = (index + 1) % tabs.length;
        else if (event.key === "ArrowLeft") next = (index - 1 + tabs.length) % tabs.length;
        else if (event.key === "Home") next = 0;
        else if (event.key === "End") next = tabs.length - 1;
        else return;
        event.preventDefault();
        activate(tabs[next], true);
      });
    });
    var initiallySelected = tabs.find(function (tab) { return tab.getAttribute("aria-selected") === "true"; }) || tabs[0];
    activate(initiallySelected, false);
  }
  function initializeAll() { document.querySelectorAll(selector).forEach(initialize); }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", initializeAll);
  else initializeAll();
})();
